struct Disk {
 fs::path file=root/"state.json";unsigned writes=0;bool before=false,after=false;
 void save(const Json&j){if(before){before=false;throw JsonError("synthetic precommit failure");}auto temp=file;temp+=".tmp";{std::ofstream out(temp,std::ios::binary);out<<j.dump();out.flush();check(bool(out),"synthetic fixture write");}fs::rename(temp,file);++writes;if(after){after=false;throw JsonError("synthetic lost response after commit");}}
 Json load(){std::ifstream in(file,std::ios::binary);return Json::parse(std::string((std::istreambuf_iterator<char>(in)),{}),8388608,32,524288);}
 ~Disk(){std::error_code error;fs::remove(file,error);auto temp=file;temp+=".tmp";fs::remove(temp,error);}
};
