void capacityReopenExpand(){
 Disk disk;ContentStore store(fullLegacy(),[&](const Json&j){disk.save(j);},LegacyLearningCapacity);bind(store);auto added=intent(store,"待入账");auto before=disk.writes;
 auto result=store.acceptLearningIntent(added,1000);check(result.status==LearningIntentStatus::Pending&&disk.writes==before+1,"capacity rejection durably accepts exactly one pending commit");check(store.current().at("archive").at("entries").items.size()==5000,"pending never truncates model");
 ContentStore resumed(disk.load(),[&](const Json&j){disk.save(j);},LegacyLearningCapacity);before=disk.writes;check(resumed.acceptLearningIntent(added,1001).status==LearningIntentStatus::Duplicate&&disk.writes==before,"reopen and same intent do not add or rewrite");
 auto existing=intent(resumed,"合成0",1001);check(resumed.acceptLearningIntent(existing,1001).status==LearningIntentStatus::Applied&&word(resumed,"合成0").at("counts").at(Actor).num()==2,"full new-word pending cannot block existing term");
 before=disk.writes;for(unsigned i=0;i<5;++i)check(resumed.retryLearningIntents(1002+i)==0,"full-profile retry makes no progress");check(disk.writes==before,"idle full-profile retry performs no saves");
 resumed.upgradeLearningCapacity("expanded-10000",2);check(resumed.current().at("version").num()==2&&resumed.current().at("archive").at("version").num()==2,"explicit known profile migration persisted");
 check(resumed.retryLearningIntents(2000)==1&&word(resumed,"待入账").at("counts").at(Actor).num()==1,"production v2 replays old durable pending once beyond source freshness window");
 ContentStore final(disk.load(),[&](const Json&j){disk.save(j);});before=disk.writes;check(final.acceptLearningIntent(added,2001).status==LearningIntentStatus::Duplicate&&disk.writes==before,"lost ACK after replay cannot count twice");check(final.retryLearningIntents(2001)==0,"completed intent no longer pending");
 check(word(final,"合成0").at("pinned").boolean()&&word(final,"合成0").at("pinVersion").at("sequence").num()==3&&word(final,"合成1").at("deleted").boolean()&&word(final,"合成2").at("generation").num()==2,"all old pin/tombstone/generation controls retained");
 reject([&]{ContentStore legacy(disk.load(),[](const Json&){},LegacyLearningCapacity);},"v1 reader rejects persisted v2 even if capacity looks small");
}
void atomicCommitFailures(){
 Disk disk;ContentStore store({},[&](const Json&j){disk.save(j);});bind(store);auto event=intent(store,"原子词");const auto before=store.current().dump();disk.before=true;reject([&]{store.acceptLearningIntent(event,1000);},"save failure cannot ACK");check(store.mustReload()&&store.current().dump()==before&&disk.load().dump()==before,"precommit failure preserves disk and old RAM and requires reload");
 ContentStore restored(disk.load(),[&](const Json&j){disk.save(j);});auto writes=disk.writes;check(restored.acceptLearningIntent(event,1001).status==LearningIntentStatus::Applied&&disk.writes==writes+1,"normal archive plus receipt uses one original save");
 auto second=intent(restored,"原子词",1002);disk.after=true;reject([&]{restored.acceptLearningIntent(second,1002);},"postcommit lost response is not a new success reply");check(restored.mustReload(),"ambiguous save prevents further cached writes");reject([&]{restored.acceptLearningIntent(second,1003);},"cached owner cannot overwrite committed receipt");
 ContentStore reopened(disk.load(),[&](const Json&j){disk.save(j);});writes=disk.writes;check(reopened.acceptLearningIntent(second,1003).status==LearningIntentStatus::Duplicate&&disk.writes==writes&&word(reopened,"原子词").at("counts").at(Actor).num()==2,"reopen resolves committed lost ACK exactly once");
}
